// 1. Cargar archivo (Sin borrar caché)
const parser = require('/home/node/virgo_files/functions/parse_special_codes.js');

// 2. Obtener datos de entrada
const item = $input.first();
const aiResponse = item.json.output || item.json.text || "";

// 3. Preparar contexto
const webhookData = $('Webhook').first().json.body.payload;
const context = { 
  phone: webhookData.from,
  executionId: $execution.id 
};

// 4. Ejecutar función externa
const result = parser(aiResponse, context);

// ---------------------------------------------------------
// 5. 🛠️ PARCHES Y ETIQUETAS SECRETAS
// ---------------------------------------------------------

const citaCode = result.detected_codes.find(c => c.code === 'CITA_CONFIRMADA');

if (citaCode && citaCode.value && citaCode.value.includes('[SPLIT]')) {
    result.message_to_user = citaCode.value.split('MEMORY_UPDATE')[0].trim();
} else if (result.message_to_user) {
    result.message_to_user = result.message_to_user.split('MEMORY_UPDATE')[0].trim();
}

// A. Rescate de Nombre
if (aiResponse.includes('ACTUALIZAR_NOMBRE')) {
    const regexNombre = /ACTUALIZAR_NOMBRE\s*\|\s*([^|]+)\s*\|/;
    const match = aiResponse.match(regexNombre);
    if (match && match[1]) {
        result.nombre_detectado = match[1].trim(); 
    }
}

// A.2 Rescate de Vacante
if (aiResponse.includes('ACTUALIZAR_VACANTE')) {
    const regexVacante = /ACTUALIZAR_VACANTE\s*\|\s*([^|]+)\s*\|/;
    const matchVacante = aiResponse.match(regexVacante);
    if (matchVacante && matchVacante[1]) {
        result.vacante_detectada = matchVacante[1].trim(); 
    }
}

// 🆕 A.3 Rescate de Nave (NUEVO)
if (aiResponse.includes('ACTUALIZAR_NAVE')) {
    const regexNave = /ACTUALIZAR_NAVE\s*\|\s*([^|]+)\s*\|/;
    const matchNave = aiResponse.match(regexNave);
    if (matchNave && matchNave[1]) {
        result.nave_detectada = matchNave[1].trim(); 
    }
}

// B. Rescate de Privacidad
if (aiResponse.includes('PRIVACIDAD_ACEPTADA')) {
    result.acepto_privacidad = true;
}

// C. Rescate de Alerta Humana
if (aiResponse.includes('HUMAN_ALERT')) {
    let fragmento = aiResponse.split('HUMAN_ALERT')[1].split('MEMORY_UPDATE')[0];
    let partes = fragmento.split('|');
    result.message_to_user = partes[partes.length - 1].trim();
}

// D. 🚨 RESCATE DE CV MANUAL (A PRUEBA DE FALLOS Y MARKDOWN)
if (aiResponse.includes('CV_MANUAL')) {
    const regexCV = /CV_MANUAL[\s|]*(\{[\s\S]*?\})/i;
    const matchCV = aiResponse.match(regexCV);

    if (matchCV && matchCV[1]) {
        try {
            // Destruimos cualquier comilla de markdown o salto de línea que la IA intente meter
            let jsonLimpio = matchCV[1].replace(/```json/gi, '').replace(/```/g, '').replace(/[\n\r\t]/g, ' ').trim();
            const cvData = JSON.parse(jsonLimpio);

            result.experiencia_manual = cvData.experiencia;
            result.vacante_manual = cvData.vacante;
            result.datos_cv_manual = cvData; 
            result.es_cv_manual = true; 

            if(cvData.nombre && cvData.nombre !== "Desconocido") {
                result.nombre_detectado = cvData.nombre;
            }
        } catch(e) {
            result.datos_cv_manual = { 
                "error": "La IA formateó mal el JSON", 
                "experiencia": "Candidato llenó solicitud manual por chat." 
            };
            result.es_cv_manual = true;
        }
    }
}

// Rescate de Filtros Técnicos tolerante a errores
if (aiResponse.includes('RESPUESTAS_FILTRO')) {
    const regexFiltro = /RESPUESTAS_FILTRO[\s:|]*(.*?)([|\n]|$)/i;
    const matchFiltro = aiResponse.match(regexFiltro);
    if (matchFiltro && matchFiltro[1]) {
        result.respuestas_filtro_detectadas = matchFiltro[1].replace(/\|/g, '').trim();
    }
}

// E. Limpieza Visual Profunda
if (result.message_to_user) {
    result.message_to_user = result.message_to_user.replace(/ACTUALIZAR_NOMBRE\s*\|\s*[^|]+\s*\|/gi, '').trim();
    result.message_to_user = result.message_to_user.replace(/PRIVACIDAD_ACEPTADA\s*\|?/gi, '').trim();

    result.message_to_user = result.message_to_user.replace(/CV_MANUAL[\s:|]*\{[\s\S]*?\}[\s|]*/gi, '').trim();
    result.message_to_user = result.message_to_user.replace(/```json/gi, '').replace(/```/g, '').trim();

    result.message_to_user = result.message_to_user.replace(/RESPUESTAS_FILTRO[\s:|]*(.*?)([|\n]|$)/gi, '').trim();
    result.message_to_user = result.message_to_user.replace(/ACTUALIZAR_VACANTE\s*\|\s*[^|]+\s*\|/gi, '').trim();
    result.message_to_user = result.message_to_user.replace(/CITA_CONFIRMADA[\s:|]*(.*?)([|\n]|$)/gi, '').trim();

    // 🆕 Limpiamos la nueva etiqueta para que el candidato no la vea
    result.message_to_user = result.message_to_user.replace(/ACTUALIZAR_NAVE\s*\|\s*[^|]+\s*\|/gi, '').trim();

    if (aiResponse.includes('CITA_CANCELADA')) {
          result.cita_cancelada = true;
    }

    if (result.fecha_entrevista_detectada) {
        result.message_to_user = result.message_to_user.replace(result.fecha_entrevista_detectada, '').replace(/\|/g, '').trim();
    }

    result.message_to_user = result.message_to_user.replace(/^[|\s]+/, '').trim();
}

// F. Rescate de Fecha de Entrevista
if (aiResponse.includes('CITA_CONFIRMADA')) {
    const regexCita = /CITA_CONFIRMADA[\s:|]*(.*?)([|\n]|$)/i;
    const matchCita = aiResponse.match(regexCita);
    if (matchCita && matchCita[1]) {
        result.fecha_entrevista_detectada = matchCita[1].replace(/\|/g, '').trim();
    }
}

// ---------------------------------------------------------
// 6. 🚀 LA MAGIA DE HUMANIZACIÓN: SPLIT DE MENSAJES
// ---------------------------------------------------------
let mensajes = [result.message_to_user];

if (result.message_to_user && result.message_to_user.includes('[SPLIT]')) {
    mensajes = result.message_to_user.split(/\[SPLIT\]/i).map(m => m.trim()).filter(m => m !== "");
}

let output = [];
for (let msg of mensajes) {
    let itemCopia = JSON.parse(JSON.stringify(result));
    itemCopia.message_to_user = msg;

    if(result.nombre_detectado) itemCopia.nombre_detectado = result.nombre_detectado;
    if(result.acepto_privacidad) itemCopia.acepto_privacidad = true;
    if(result.experiencia_manual) itemCopia.experiencia_manual = result.experiencia_manual;
    if(result.vacante_manual) itemCopia.vacante_manual = result.vacante_manual;
    if(result.respuestas_filtro_detectadas) itemCopia.respuestas_filtro_detectadas = result.respuestas_filtro_detectadas;
    if(result.vacante_detectada) itemCopia.vacante_detectada = result.vacante_detectada;
    if(result.datos_cv_manual) itemCopia.datos_cv_manual = result.datos_cv_manual;
    if(result.es_cv_manual) itemCopia.es_cv_manual = result.es_cv_manual;
    if(result.fecha_entrevista_detectada) itemCopia.fecha_entrevista_detectada = result.fecha_entrevista_detectada;

    // 🆕 Empaquetamos la nave detectada para mandarla a la Base de Datos
    if(result.nave_detectada) itemCopia.nave_detectada = result.nave_detectada;

    output.push({ json: itemCopia });
}

return output;

