const fs = require('fs');

let prompt = fs.readFileSync('/home/node/virgo_files/prompts/chat_prompt.md', 'utf8');
let menuNavesTxt = "";
try { menuNavesTxt = fs.readFileSync('/home/node/virgo_files/prompts/menu_naves.txt', 'utf8'); } catch(e) {}

const webhookData = $('Webhook').first().json.body.payload || {};
const dbData = $('ObtenerDatosCandidato').first()?.json || {}; 

let naveActual = dbData.nave_interes || "";
let menuTxt = "Aún no has seleccionado una sucursal.";
let detalleTxt = "Información no disponible.";

if (naveActual) {
    try { menuTxt = fs.readFileSync(`/home/node/virgo_files/prompts/menu_vacantes_${naveActual}.txt`, 'utf8'); } catch(e) {}
    try { detalleTxt = fs.readFileSync(`/home/node/virgo_files/prompts/detalle_vacantes_${naveActual}.txt`, 'utf8'); } catch(e) {}
} else {
    naveActual = "Pendiente";
}

const timeZone = 'America/Mexico_City';
const nowObj = new Date();
const fechaActual = nowObj.toLocaleString('es-MX', { timeZone, weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', hour: 'numeric', minute: 'numeric', hour12: true });
const anioActual = nowObj.getFullYear();
const mananaObj = new Date(nowObj);
mananaObj.setDate(mananaObj.getDate() + 1);
const fechaManana = mananaObj.toLocaleDateString('es-MX', { timeZone, weekday: 'long', day: 'numeric', month: 'long' });

let nombreReal = dbData.nombre_chat || dbData.nombre_ine || dbData.nombre_solicitud || 'Desconocido';
if (nombreReal === 'Candidato' || nombreReal === 'No registrado') nombreReal = 'Desconocido'; 

let semaforoIne = "PENDIENTE"; 
if (dbData.nombre_confirmado === true || dbData.estado === 'INE_VALIDADA' || dbData.cv_manual) semaforoIne = "VERIFICADO";

prompt = prompt.replace(/{{NOMBRE_WHATSAPP}}/g, webhookData._data?.notifyName || 'Usuario');
prompt = prompt.replace(/{{TELEFONO_ID}}/g, $('GetInfo').first().json.number);
prompt = prompt.replace(/{{NAVE_ACTUAL}}/g, naveActual);
prompt = prompt.replace(/{{MENU_NAVES}}/g, menuNavesTxt);
prompt = prompt.replace(/{{MENU_VACANTES}}/g, menuTxt);
prompt = prompt.replace(/{{DETALLE_VACANTES}}/g, detalleTxt);
prompt = prompt.replace(/{{FECHA_HORA_ACTUAL}}/g, fechaActual);
prompt = prompt.replace(/{{FECHA_MANANA}}/g, fechaManana);
prompt = prompt.replace(/{{ANIO_ACTUAL}}/g, anioActual);
prompt = prompt.replace(/{{STATUS_INE}}/g, semaforoIne); 
prompt = prompt.replace(/{{NOMBRE_REGISTRADO}}/g, nombreReal);
prompt = prompt.replace(/{{ESTADO_ACTUAL}}/g, dbData.estado || 'NUEVO');
prompt = prompt.replace(/{{VACANTE_INTERES}}/g, dbData.vacante_interes || 'Ninguna');
prompt = prompt.replace(/{{RESUMEN_ANTERIOR}}/g, dbData.resumen_ia || 'Conversación nueva.');

return { json: { system_prompt_procesado: prompt } };

// 1. OBTENER EL JSON LIMPIO DE GEMINI
const item = $input.first();
const rawText = item.json.content?.parts?.[0]?.text || item.json.output || item.json.text || "{}";

const jsonMatch = rawText.match(/\{[\s\S]*\}/);
const cleanJson = jsonMatch ? jsonMatch[0] : rawText.replace(/```json|```/g, '').trim();

let datos = {};
try { datos = JSON.parse(cleanJson); } catch (e) { datos = {}; }

// 2. EXTRAER VARIABLES BÁSICAS
const tipo = (datos.tipo_documento || "GENERICO").toUpperCase();
const nombreOriginal = datos.nombre_completo || "Candidato";
const nombreLimpio = nombreOriginal
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9 ]/g, "")
    .replace(/\s+/g, "_");
const vacanteAnuncio = datos.vacante_anuncio || "General";

let telefono = $('GetInfo').first().json.number;

// 3. RENOMBRAR ARCHIVO FÍSICO
let binaryData = {};
try { binaryData = $('DescargarMedia').first().binary; } catch(e) { binaryData = item.binary; }

if (binaryData) {
    const key = Object.keys(binaryData)[0];
    if (binaryData[key]) {
        const ext = (binaryData[key].fileExtension || "pdf").replace('.', '');
        binaryData[key].fileName = `${tipo}_${nombreLimpio}_${telefono}.${ext}`;
    }
}

let edadCalculada = null;
if (datos.fecha_nacimiento && datos.fecha_nacimiento !== "No visible" && datos.fecha_nacimiento !== "null") {
    const matchAno = datos.fecha_nacimiento.match(/\d{4}/);
    if (matchAno) {
        edadCalculada = (new Date().getFullYear() - parseInt(matchAno[0])).toString() + " años";
    }
}
let nombreWhatsApp = $('Webhook').first().json.body.payload._data?.notifyName || "Candidato";

// 4. LÓGICA DEL MENSAJE PARA SOFÍA (AI CHAT)
const dbData = $('ObtenerDatosCandidato').first().json || {};
let msgUsuario = datos.mensaje_usuario || ""; 

// 🚀 MAGIA: Rescatamos el texto del candidato que acompaña a la imagen
const captionUsuario = $('Webhook').first().json.body.payload.body || "";

if (!msgUsuario || msgUsuario === "null") {
    if (tipo === "SOLICITUD" && dbData.estado !== 'CV_RECIBIDO') {
        msgUsuario = "El candidato acaba de enviar la PRIMERA foto de su solicitud (frente). Agradécele e indícale que por favor envíe también la foto de la PARTE TRASERA para tener su expediente completo. Dile que si su solicitud solo tiene un lado o ya mandó ambas, responda 'Listo'.";
    } else if (tipo === "ANUNCIO") {
        // Armamos el contexto de la imagen + lo que escribió el usuario
        msgUsuario = `[SISTEMA: El candidato te envió una captura de pantalla del anuncio de la vacante: *${vacanteAnuncio}*.`;
        if (captionUsuario) {
            msgUsuario += ` Además, escribió este mensaje: "${captionUsuario}".`;
        }
        msgUsuario += ` OBLIGATORIO: Atiéndelo de forma natural, asume que le interesa esa vacante y muéstrale los detalles o pregúntale si quiere aplicar.]`;
    } else if (tipo === "INE") {
        if (dbData.datos_rfc) {
            msgUsuario = "[SISTEMA: AMBOS DOCUMENTOS COMPLETOS. El candidato entregó INE y RFC. Revisa INMEDIATAMENTE tu calendario y ofrécele fechas de entrevista.]";
        } else {
            msgUsuario = "[SISTEMA: El candidato entregó su INE, pero FALTA SU CONSTANCIA. Agradécele por el INE y pídele obligatoriamente su Constancia de Situación Fiscal (RFC). TIENES ESTRICTAMENTE PROHIBIDO AGENDAR CITA AÚN.]";
        }
    } else if (tipo === "CONSTANCIA") {
        if (dbData.datos_ine) {
            msgUsuario = "[SISTEMA: AMBOS DOCUMENTOS COMPLETOS. El candidato entregó INE y RFC. Revisa INMEDIATAMENTE tu calendario y ofrécele fechas de entrevista.]";
        } else {
            msgUsuario = "[SISTEMA: El candidato entregó su Constancia (RFC), pero FALTA SU INE. Agradécele por la Constancia y pídele obligatoriamente la foto frontal de su INE. TIENES ESTRICTAMENTE PROHIBIDO AGENDAR CITA AÚN.]";
        }
    } else if (tipo === "CV" || (tipo === "SOLICITUD" && dbData.estado === 'CV_RECIBIDO')) {
        if (!datos.correo) {
            msgUsuario = "[SISTEMA: CV Recibido. Pregunta ÚNICAMENTE: '¡Recibí tu documento y tu perfil está súper bien! 👏 Antes de continuar, ¿me podrías proporcionar tu correo electrónico, por favor? 📧']";
        } else {
            msgUsuario = "[SISTEMA: CV Recibido. Pregunta ÚNICAMENTE: '¡Recibí tu documento y tu perfil está súper bien! 👏 Antes de continuar, me gustaría hacerte una pregunta rápida: ¿Te encuentras laborando actualmente? 💼']";
        }
    } else {
        msgUsuario = "El candidato envió un documento. Confírmale de recibido de forma amable.";
    }
} else if (tipo === "ANUNCIO") {
    msgUsuario = `[SISTEMA: El candidato te envió una foto del anuncio de la vacante: *${vacanteAnuncio}*. Mensaje: "${captionUsuario}". Atiéndelo.]`;
}

// 5. SALIDA
return {
    json: {
        nombre: nombreOriginal,
        telefono: telefono,
        tipo_origen: tipo,
        cv_manual: datos,
        experiencia: datos.experiencia || "",
        veredicto: datos.veredicto || null,
        motivo: datos.motivo || null,
        resumen_excel: datos.resumen_excel || null,
        fecha_nacimiento: datos.fecha_nacimiento || "No visible",
        vacante_anuncio: vacanteAnuncio,
        mensaje_usuario: msgUsuario,
        edad_calculada: edadCalculada,
        nombre_chat: nombreWhatsApp,
        correo: datos.correo || null,
    },
    binary: binaryData
};

