let vacante = (dbData.vacante_interes || "General").toLowerCase();
let naveActual = dbData.nave_interes || "1"; // Si por algo falla, lo mandamos a la Nave 1 por defecto

// 2. CARGAR EL EQUIPO REAL
const rutaArchivo = '/home/node/virgo_files/functions/config_reclutadores.json';
let equipo = [];

try {
    equipo = JSON.parse(fs.readFileSync(rutaArchivo, 'utf8'));
} catch (e) {
    // Si el archivo falla, creamos un salvavidas
    equipo = [{ 
        "nombre": "Gerente de Reclutamiento", 
        "telefono": "5213332012658", 
        "calendar_id": "talreclutamiento01@gmail.com",
        "naves": ["1", "2", "3", "4", "5"],
        "palabras_clave": ["general"]
    }];
}

// 3. LÓGICA DE ASIGNACIÓN DUAL (NAVE + VACANTE)
let asignado = equipo[equipo.length - 1]; // Por defecto, se lo mandamos al último de la lista (Coordinación)

for (const reclutador of equipo) {
    // A. ¿Este reclutador atiende la Nave que eligió el candidato?
    // (Soporta tanto el formato de lista ["1", "2"] como un texto simple "1"
    let atiendeNave = false;
    if (Array.isArray(reclutador.naves)) {
        atiendeNave = reclutador.naves.includes(naveActual);
    } else if (reclutador.id_nave) {
        atiendeNave = reclutador.id_nave === naveActual;
    }

    if (atiendeNave) {
        // B. Si sí atiende la Nave, ¿atiende también el puesto (vacante)?
        const atiendeVacante = reclutador.palabras_clave && reclutador.palabras_clave.some(p => vacante.includes(p));

        if (atiendeVacante) {
            asignado = reclutador;
            break; // ¡Lo encontramos! Detenemos la búsqueda
        }
    }
}

// 4. SALIDA AL SIGUIENTE NODO
return {
    json: {
        nombre_reclutador: asignado.nombre,
        telefono_reclutador: asignado.telefono,
        calendar_id: asignado.calendar_id,
        vacante_detectada: vacante,
        nave_candidato: naveActual
    }
};

